 [{"id":"d4b1af6","elType":"container","settings":[],"elements":[{"id":"fc49f00","elType":"widget","settings":{"html":"<div style="display:flex; justify-content:center; align-items:center; min-height:60vh;">
 <div id="qr-wrapper" style="text-align:center; color:#000;">
 <p id="qr-message" style="color:#000;">
 Save and print the QR Code below and create your own poster to display at your point of sale.
 </p>

 <p id="qr-url" style="color:#000; font-size:14px; word-break:break-all; margin-bottom:16px;"></p>

 <div style="margin-bottom:16px;">
 <label for="qr-color" style="color:#000; font-size:14px; margin-right:8px;">
 QR color:
 </label>
 <input id="qr-color" type="color" value="#000000" style="margin-right:16px;">

 <label for="qr-bgcolor" style="color:#000; font-size:14px; margin-right:8px;">
 Background:
 </label>
 <input id="qr-bgcolor" type="color" value="#FFFFFF">
 </div>

 <img id="qr-image" alt="QR code for previous page"
 style="max-width:1024px; display:block; margin:0 auto 24px auto;">

 <button id="qr-download" type="button"
 style="margin-top:16px; padding:8px 16px; color:#000; margin-right:8px;">
 Download QR
 </button>

 <button id="qr-copy" type="button"
 style="margin-top:16px; padding:8px 16px; color:#000;">
 Copy Link
 </button>
 </div>
</div>

<script>
 (function() {
 var ref = document.referrer;

 if (!ref) {
 document.getElementById('qr-message').innerText =
 'No previous page detected. Please go back to the page you want and use the menu link again.';
 return;
 }

 var a = document.createElement('a');
 a.href = ref;
 if (a.hostname.indexOf('securemetawork.com') === -1) {
 document.getElementById('qr-message').innerText =
 'Previous page is external, not generating a QR.';
 return;
 }

 var urlText = document.getElementById('qr-url');
 var imgEl = document.getElementById('qr-image');
 var colorEl = document.getElementById('qr-color');
 var bgColorEl = document.getElementById('qr-bgcolor');

 urlText.innerText = 'This QR code links to: ' + ref;

 function updateQr() {
 var encoded = encodeURIComponent(ref);
 var hex = colorEl.value.replace('#', ''); // foreground color
 var bgHex = bgColorEl.value.replace('#', ''); // background color
 var qrSrc =
 'https://api.qrserver.com/v1/create-qr-code/?size=256x256' +
 '&data=' + encoded +
 '&color=' + hex +
 '&bgcolor=' + bgHex; // both supported by the API[web:132]
 imgEl.src = qrSrc;
 }

 // Initial QR
 updateQr();

 // Regenerate when colors change
 colorEl.addEventListener('input', updateQr);
 bgColorEl.addEventListener('input', updateQr);

 // Download button (Blob method for direct download)
 var btnDownload = document.getElementById('qr-download');
 btnDownload.addEventListener('click', async function () {
 if (!imgEl.src) return;
 try {
 const response = await fetch(imgEl.src);
 const blob = await response.blob(); // turn image into Blob[web:174]
 const url = URL.createObjectURL(blob);
 const link = document.createElement('a');
 link.href = url;
 link.download = 'qr-code.png';
 document.body.appendChild(link);
 link.click();
 document.body.removeChild(link);
 URL.revokeObjectURL(url);
 } catch (e) {
 alert('Could not download the QR image.');
 }
 });

 // Copy link button
 var btnCopy = document.getElementById('qr-copy');
 btnCopy.addEventListener('click', function () {
 if (!navigator.clipboard || !navigator.clipboard.writeText) {
 var temp = document.createElement('textarea');
 temp.value = ref;
 document.body.appendChild(temp);
 temp.select();
 document.execCommand('copy');
 document.body.removeChild(temp);
 alert('Link copied to clipboard');
 } else {
 navigator.clipboard.writeText(ref).then(function () {
 alert('Link copied to clipboard');
 }, function () {
 alert('Could not copy link');
 });
 }
 });
 })();
</script>
"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"4e65c538","elType":"container","settings":[],"elements":[],"isInner":false}]
